file.content:
                        VC_CONFIG_FILE
                    )
                })?;
                let bot = toml_simple::toml_get(&cfg.map, "repos.bot")
                    .filter(|v| !v.is_empty())
                    .ok_or(
                        "--scope=bot: no bot repo configured. Add `bot = \"...\"` to the \
                         [repos] registry to enable dual-repo operations",
                    )?;
                repos.push(resolve_repo_path(root, bot));
            }
        }
    }
    Ok(repos)
}

/// Resolve the workspace's bot-repo path, or `None` when it has no
/// bot side.
///
/// The scope-aware prelude for commands that *optionally* work
/// against the bot repo (validate-desc / fix-desc): topology comes
/// from `default_scope` (the workspace config), not a flag:
/// `Ok(None)` means a POR / single-repo workspace, the caller's
/// no-op case, while a configured-but-broken bot side still errors
/// via `scope_to_repos`.
pub fn bot_repo_path(workspace_root: &Path) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
    match configured_bot_dir(workspace_root)? {
        Some(bot) => {
            verify_workspace_coherence(workspace_root, &bot)?;
            Ok(Some(bot))
        }
        None => Ok(None),
    }
}

/// The bot dir the workspace config *declares*: a pure config
/// read, no on-disk verification.
///
/// The pre-coherence half of [`bot_repo_path`], for callers that
/// resolve the dir before it exists (clone names the local clone
/// destination from the just-cloned work repo's config). `Ok(None)`
/// when the workspace declares no bot side.
pub fn configured_bot_dir(
    workspace_root: &Path,
) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
    reject_legacy_config(workspace_root)?;
    if !default_scope(Some(workspace_root)).has_bot() {
        return Ok(None);
    }
    let repos = scope_to_repos(&Scope(vec![Side::Bot]), Some(workspace_root))?;
    match repos.as_slice() {
        [bot] => Ok(Some(bot.clone())),
        other => Err(format!(
            "configured_bot_dir: expected one repo from scope_to_repos, got {}",
            other.len()
        )
        .into()),
    }
}

/// Resolve the bot repo of a workspace that *requires* one.
///
/// The dual-only sibling of [`bot_repo_path`] for operations that
/// make no sense without a bot side (push): `None` becomes a loud
/// error instead of a no-op signal.
pub fn require_bot_dir(workspace_root: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
    bot_repo_path(workspace_root)?.ok_or_else(|| {
        format!(
            "{}'s config declares no bot repo (`repos.bot`): \
             this operation requires a dual workspace",
            workspace_root.display()
        )
        .into()
    })
}

/// Dual-mode entry preflight: verify the two repos' recorded
/// topology agrees before any operation acts on it.
///
/// Checks, in order, erroring with everything known and changing
/// nothing (the dual-preflight principle, 2026-07-23):
///
/// - the bot dir exists (and is a directory);
/// - its `.vc-config.toml` loads;
/// - **resolved agreement**: each side's declared `[repos]` pair,
///   resolved file-relative and canonicalized, names the same two
///   directories (the file-relative schema makes the raw blocks
///   asymmetric by design, so agreement is checked on resolved
///   reality, not spelling);
/// - **self-identification**: each config's own directory sits at
///   its side's key (root's `work`, bot's `bot`): agreement
///   alone can't catch both sides naming the same wrong pair.
///
/// Mid-flight surprises stay per-operation concerns; this gates
/// *entry* at the one topology resolver.
fn verify_workspace_coherence(root: &Path, bot: &Path) -> Result<(), Box<dyn std::error::Error>> {
    if !bot.is_dir() {
        return Err(format!(
            "workspace incoherent: {}/.vc-config.toml declares bot repo '{}', \
             but that directory does not exist, fix the `bot` value or \
             restore the directory; nothing was changed",
            root.display(),
            bot.display()
        )
        .into());
    }
    let root_cfg = crate::config_md::load(root)?.ok_or_else(|| {
        format!(
            "workspace incoherent: no vc-x1 config found in '{}'; \
             nothing was changed",
            root.display()
        )
    })?;
    let bot_cfg = match crate::config_md::load(bot) {
        Ok(Some(cfg)) => cfg,
        Ok(None) => {
            return Err(format!(
                "workspace incoherent: bot repo '{}' has no vc-x1 config \
                 ({} or {VC_CONFIG_FILE}): both sides must carry a [repos] \
                 registry naming the same directories; nothing was changed",
                bot.display(),
                crate::config_md::VC_CONFIG_MD
            )
            .into());
        }
        Err(e) => {
            return Err(format!(
                "workspace incoherent: bot repo '{}' has no readable config \
                 ({e}): both sides must carry a [repos] registry naming the \
                 same directories; nothing was changed",
                bot.display()
            )
            .into());
        }
    };
    let (root_pair, bot_pair) = (
        resolved_repos_pair(root, &root_cfg)?,
        resolved_repos_pair(bot, &bot_cfg)?,
    );
    if root_pair != bot_pair {
        return Err(format!(
            "workspace incoherent: the two sides' [repos] registries resolve to \
             different directories: they must name the same work/bot pair; \
             nothing was changed\n\
             {}: work={}, bot={}\n\
             {}: work={}, bot={}",
            root_cfg.path.display(),
            root_pair.0.display(),
            root_pair.1.display(),
            bot_cfg.path.display(),
            bot_pair.0.display(),
            bot_pair.1.display()
        )
        .into());
    }
    // Self-identification: agreement alone can't catch both sides
    // naming the same *wrong* pair: each config's own directory
    // must sit at its side's key.
    let canon_root = root.canonicalize()?;
    if root_pair.0 != canon_root {
        return Err(format!(
            "workspace incoherent: {}'s `repos.work` resolves to \
             '{}', not to the workspace root itself: the work side's own entry \
             must name its own directory; nothing was changed",
            root_cfg.path.display(),
            root_pair.0.display()
        )
        .into());
    }
    let canon_bot = bot.canonicalize()?;
    if bot_pair.1 != canon_bot {
        return Err(format!(
            "workspace incoherent: {}'s `repos.bot` resolves to \
             '{}', not to the bot repo itself: the bot side's own entry must \
             name its own directory; nothing was changed",
            bot_cfg.path.display(),
            bot_pair.1.display()
        )
        .into());
    }
    Ok(())
}

/// Resolve and canonicalize one side's declared `[repos]` pair.
///
/// The per-side half of the resolved-agreement check: reads
/// `repos.work` / `repos.bot` from `cfg` (the config loaded at
/// `cfg_dir`), resolves each file-relative, and canonicalizes:
/// a missing key or unresolvable directory is its own coherence
/// error.
fn resolved_repos_pair(
    cfg_dir: &Path,
    cfg: &crate::config_md::VcConfig,
) -> Result<(PathBuf, PathBuf), Box<dyn std::error::Error>> {
    let resolve = |key: &str| -> Result<PathBuf, Box<dyn std::error::Error>> {
        let value = toml_simple::toml_get(&cfg.map, key)
            .filter(|v| !v.is_empty())
            .ok_or_else(|| {
                format!(
                    "workspace incoherent: {} has no `{key}` in its \
                     [repos] registry: both sides must declare the work/bot pair; \
                     nothing was changed",
                    cfg.path.display()
                )
            })?;
        resolve_repo_path(cfg_dir, value)
            .canonicalize()
            .map_err(|e| {
                format!(
                    "workspace incoherent: {}'s `{key}` (\"{value}\") does \
                 not resolve to an existing directory ({e}); nothing was changed",
                    cfg.path.display()
                )
                .into()
            })
    };
    Ok((resolve("repos.work")?, resolve("repos.bot")?))
}

