100	/// Owned dual-repo fixture with RAII cleanup.
101	///
102	/// Builds a fresh throwaway dual-repo set under a unique tempdir
103	/// by driving `init::init` with a path TARGET and `--repo
104	/// local=<base>` (so config lookup is skipped via the
105	/// resolve_repo short-circuit). `create_symlink=false` suppresses
106	/// the `~/.claude/projects/` side effect. Exposes the two repo
107	/// paths (`work` and `work/.claude`). The tempdir tree is removed
108	/// when the value is dropped, so a panicking test still cleans up
109	/// after itself.
110	pub struct Fixture {
111	    /// Root tempdir that owns both repos and their bare-git remotes.
112	    pub base: PathBuf,
113	    /// Work repo path (`<base>/work`).
114	    pub work: PathBuf,
115	    /// Bot repo path (`<base>/work/.claude`).
116	    pub bot: PathBuf,
117	}
118	
119	impl Fixture {
120	    /// Build a fresh fixture in a unique tempdir.
121	    pub fn new(tag: &str) -> Self {
122	        Self::new_opts(tag, false, None)
123	    }
124	
125	    /// Build a fresh fixture with optional pending changes and a
126	    /// template seed.
127	    ///
128	    /// - `with_pending`: after init, write a small file into each
129	    ///   repo so `@` carries uncommitted changes (useful for
130	    ///   squash-push / push tests).
131	    /// - `use_template`: `WORK[,BOT]` forwarded to init.
132	    pub fn new_opts(tag: &str, with_pending: bool, use_template: Option<String>) -> Self {
133	        let base = unique_base(tag);
134	        // init refuses to reuse an existing project_dir, so `base`
135	        // must not exist yet. `unique_base` already guarantees that.
136	        //
137	        // Path TARGET = `<base>/work` (workspace destination); the
138	        // basename ("work") becomes the repo name. `--repo local=<base>`
139	        // sets the bare-repo parent so the layout mirrors the old
140	        // `--repo-local <base>` + NAME=`work` shape:
141	        //   <base>/work/                  (work repo)
142	        //   <base>/work/.claude/          (bot repo)
143	        //   <base>/remote-work.git        (work bare origin)
144	        //   <base>/remote-work.claude.git      (bot bare origin)
145	        let work_path = base.join("work");
146	        let args = InitArgs {
147	            target: work_path.to_string_lossy().into_owned(),
148	            name: None,
149	            account: AccountOption::default(),
150	            repo: RepoOption {
151	                value: Some(RepoSelector {
152	                    category: "local".to_string(),
153	                    value: Some(base.to_string_lossy().into_owned()),
154	                }),
155	            },
156	            por: PorFlag { value: false },
157	            provision: ProvisionOptionFlagBundle::default(),
158	            use_template: UseTemplateOption {
159	                value: use_template,
160	            },
161	            config: ConfigOption::default(),
162	        };
163	        let ctx = Context::load().expect("load user config for test fixture");
164	        let mut params = InitParams::from(&args);
165	        params.create_symlink = false;
166	        init(&ctx, &params).expect("build test fixture via init");
167	
168	        let work = base.join("work");
169	        let bot = work.join(".claude");
170	
171	        if with_pending {
172	            write_file(&work.join("TODO.md"), "# TODO\n- first feature\n")
173	                .expect("write pending TODO.md");
174	            write_file(
175	                &bot.join("session-notes.md"),
176	                "# Session notes\n- simulated pending work\n",
177	            )
178	            .expect("write pending session-notes.md");
179	        }
180	
181	        Fixture { base, work, bot }
182	    }
183	
184	    /// Convenience: return both repo paths as a `Vec<PathBuf>`
185	    /// suitable for `sync_repos` (or any other `&[PathBuf]` API).
186	    pub fn repos(&self) -> Vec<PathBuf> {
187	        vec![self.work.clone(), self.bot.clone()]
188	    }
189	}
