191	impl Drop for Fixture {
192	    /// Remove the fixture tree on drop. Best-effort; a failure here
193	    /// doesn't fail the test. Suppressed when `$VC_X1_TEST_KEEP` is
194	    /// set: see `test_tmp_root::should_keep_tempdir`.
195	    fn drop(&mut self) {
196	        if should_keep_tempdir() {
197	            eprintln!("VC_X1_TEST_KEEP set; preserving {}", self.base.display());
198	        } else {
199	            let _ = fs::remove_dir_all(&self.base);
200	        }
201	    }
202	}
