204	/// Owned single-repo (POR) fixture with RAII cleanup.
205	///
206	/// Sibling of `Fixture` for `--por` flows. Drives
207	/// `init::init` with `por: true` and a path TARGET;
208	/// `--repo local=<base>` steers the bare origin to
209	/// `<base>/remote.git` (vs. dual's `remote-work.git` /
210	/// `remote-work.claude.git`). No `.claude/` peer, no symlink.
211	///
212	/// Field shape differs from `Fixture` (there is no `bot` peer
213	/// path), so it's a distinct type rather than an `Option<PathBuf>`
214	/// on `Fixture` (the latter would force every dual-using caller to
215	/// `.unwrap()` or pattern-match).
216	pub struct FixturePor {
217	    /// Root tempdir that owns the repo and its bare-git remote.
218	    pub base: PathBuf,
219	    /// POR repo path (`<base>/work`).
220	    pub work: PathBuf,
221	}
