38	/// returns that block's `version`. Line-based rather than a TOML
39	/// parse: build scripts get no dev-dependencies, and the lock's
40	/// shape is fixed by cargo.
41	fn jj_lib_version(lock: &str) -> Option<String> {
42	    let mut in_jj_lib = false;
43	    for line in lock.lines() {
44	        let line = line.trim();
45	        if line == "[[package]]" {
46	            in_jj_lib = false;
47	        } else if let Some(rest) = line.strip_prefix("name = ") {
48	            in_jj_lib = rest.trim_matches('"') == "jj-lib";
