70	        // `error: <name>@<version>:` prefix already carries it.
71	        println!("cargo::error=");
72	        println!("cargo::error=A suffixed version is used with the stable package name, `vc-x1`");
73	        println!("cargo::error=so refusing to build `vc-x1` as it is the stable binary name.");
