78	/// One key parsed from the `vc-config.md` prototype, metadata
79	/// as raw strings (typing happens at render time in
80	/// `render_config_schema`).
81	struct ProtoKey {
82	    path: String,
83	    homes: Vec<String>,
84	    kind: String,
85	    doc: String,
86	    used_by: String,
87	    /// Override url; the norm is `None`, deriving
88	    /// `<reference-base>vc-config.md#<anchor_slug(path)>`.
89	    reference: Option<String>,
90	    default: Option<String>,
91	    example: Option<String>,
92	    required: bool,
93	}
