95	/// Parse a TOML basic-string body (the text between the quotes),
96	/// unescaping `\"` and `\\`. Anything fancier (unicode escapes,
97	/// multi-line strings) is out of the prototype's dialect and
98	/// fails the build via the caller's validation.
99	fn unescape_basic_string(body: &str) -> String {
100	    let mut out = String::with_capacity(body.len());
101	    let mut chars = body.chars();
102	    while let Some(c) = chars.next() {
103	        if c == '\\' {
104	            match chars.next() {
105	                Some('"') => out.push('"'),
106	                Some('\\') => out.push('\\'),
107	                other => panic!("vc-config.md: unsupported escape \\{other:?}"),
108	            }
109	        } else {
110	            out.push(c);
111	        }
112	    }
113	    out
114	}
115	
116	/// Parse one metadata value: a quoted string, a `[...]` string
117	/// array (returned joined by `\u{0}` for the caller to split), a
118	/// bare integer, or a bare bool. Returns the raw string form.
119	fn parse_value(raw: &str) -> String {
120	    let raw = raw.trim();
121	    if let Some(body) = raw.strip_prefix('"') {
122	        let Some(body) = body.strip_suffix('"') else {
123	            panic!("vc-config.md: unterminated string: {raw}");
124	        };
125	        unescape_basic_string(body)
126	    } else {
127	        raw.to_string()
128	    }
129	}
130	
131	/// Line-based parse of the prototype's TOML into `ProtoKey`s,
132	/// file order preserved. `text` is what `md_to_toml` extracted
133	/// from `vc-config.md`, so its line numbers are the file's.
134	///
135	/// Line-based for the same reason `jj_lib_version` is: build
136	/// scripts see no dev-dependencies, and the prototype's dialect
137	/// is ours to bound (single-line `key = value` entries, dotted
138	/// table headers with optionally-quoted segments, `#` comments).
139	fn parse_prototype(text: &str) -> (String, Vec<ProtoKey>) {
140	    let mut keys: Vec<ProtoKey> = Vec::new();
141	    let mut base: Option<String> = None;
142	    let mut current: Option<(String, Vec<(String, String)>)> = None;
143	
144	    fn finish(
145	        keys: &mut Vec<ProtoKey>,
146	        base: &mut Option<String>,
147	        current: Option<(String, Vec<(String, String)>)>,
148	    ) {
149	        let Some((path, fields)) = current else {
150	            return;
151	        };
152	        if path == "vc-config" {
153	            for (name, value) in fields {
154	                match name.as_str() {
155	                    "reference-base" => *base = Some(value),
156	                    other => panic!("vc-config.md: [vc-config]: unknown entry {other:?}"),
157	                }
158	            }
159	            return;
160	        }
161	        let mut homes: Vec<String> = Vec::new();
162	        let mut kind = None;
163	        let mut doc = None;
164	        let mut used_by = None;
165	        let mut reference = None;
166	        let mut default = None;
167	        let mut example = None;
168	        let mut required = false;
169	        for (name, value) in fields {
170	            match name.as_str() {
171	                "homes" => {
172	                    homes = value.split('\u{0}').map(str::to_string).collect();
173	                }
174	                "kind" => kind = Some(value),
175	                "doc" => doc = Some(value),
176	                "used-by" => used_by = Some(value),
177	                "reference" => reference = Some(value),
178	                "default" => default = Some(value),
179	                "example" => example = Some(value),
180	                "required" => match value.as_str() {
181	                    "true" => required = true,
182	                    "false" => required = false,
183	                    other => panic!("vc-config.md: [{path}] required = {other}: not a bool"),
184	                },
185	                other => panic!("vc-config.md: [{path}]: unknown entry {other:?}"),
186	            }
187	        }
188	        let missing = |what: &str| -> ! { panic!("vc-config.md: [{path}] is missing {what}") };
189	        let kind = kind.unwrap_or_else(|| missing("kind"));
190	        if !matches!(kind.as_str(), "str" | "usize" | "item-list") {
191	            panic!("vc-config.md: [{path}] kind = {kind:?}: not str/usize/item-list");
192	        }
193	        if kind == "usize"
194	            && let Some(d) = &default
195	            && d.parse::<usize>().is_err()
196	        {
197	            panic!("vc-config.md: [{path}] default {d:?} is not a usize");
198	        }
199	        if homes.is_empty() {
200	            missing("homes");
201	        }
202	        if default.is_none() && example.is_none() {
203	            missing("a default or an example");
204	        }
205	        let doc = doc.unwrap_or_else(|| missing("doc"));
206	        let used_by = used_by.unwrap_or_else(|| missing("used-by"));
207	        keys.push(ProtoKey {
208	            path,
209	            homes,
210	            kind,
211	            doc,
212	            used_by,
213	            reference,
214	            default,
215	            example,
216	            required,
217	        });
218	    }
219	
220	    for line in text.lines() {
221	        let trimmed = line.trim();
222	        if trimmed.is_empty() || trimmed.starts_with('#') {
223	            continue;
224	        }
225	        if let Some(inner) = trimmed.strip_prefix('[').and_then(|s| s.strip_suffix(']')) {
226	            finish(&mut keys, &mut base, current.take());
227	            current = Some((inner.replace('"', ""), Vec::new()));
228	            continue;
229	        }
230	        let Some((name, value)) = trimmed.split_once('=') else {
231	            panic!("vc-config.md: unparseable line: {trimmed}");
232	        };
233	        let Some((_, fields)) = current.as_mut() else {
234	            panic!("vc-config.md: entry before first table header: {trimmed}");
235	        };
236	        let name = name.trim().to_string();
237	        let raw = value.trim();
238	        let value = if name == "homes" {
239	            let Some(body) = raw.strip_prefix('[').and_then(|s| s.strip_suffix(']')) else {
240	                panic!("vc-config.md: homes must be an array: {raw}");
241	            };
242	            body.split(',')
243	                .map(|s| parse_value(s.trim()))
244	                .collect::<Vec<_>>()
245	                .join("\u{0}")
246	        } else {
247	            parse_value(raw)
248	        };
249	        fields.push((name, value));
250	    }
251	    finish(&mut keys, &mut base, current);
252	
253	    let mut paths: Vec<&str> = keys.iter().map(|k| k.path.as_str()).collect();
254	    paths.sort_unstable();
255	    paths.dedup();
256	    if paths.len() != keys.len() {
257	        panic!("vc-config.md: duplicate key path(s)");
258	    }
259	    let Some(base) = base else {
260	        panic!("vc-config.md: no [vc-config] reference-base");
261	    };
262	    (base, keys)
263	}
264	
265	/// A key path's GitHub-style heading anchor: lowercased, keeping
266	/// only `[a-z0-9-]` (dots and `<`/`>` drop out), spaces to
267	/// hyphens. `bot-session.col-width` -> `bot-sessioncol-width`,
268	/// matching the slug of that key's `##` heading in vc-config.md.
269	fn anchor_slug(path: &str) -> String {
270	    path.chars()
271	        .filter_map(|c| match c {
272	            'a'..='z' | '0'..='9' | '-' => Some(c),
273	            'A'..='Z' => Some(c.to_ascii_lowercase()),
274	            ' ' => Some('-'),
275	            _ => None,
276	        })
277	        .collect()
278	}
279	
280	/// Render the generated schema module: the `SCHEMA_GEN` table
281	/// plus one `<PATH>_DEFAULT` constant per non-dynamic defaulted
282	/// key, typed by `kind`. Each key's reference is its override
283	/// url when given, else derived from `base` + the key's
284	/// vc-config.md anchor.
285	fn render_config_schema(keys: &[ProtoKey], base: &str) -> String {
286	    let mut out = String::from(
287	        "// Generated from vc-config.md by build.rs. Do not edit.\n\
288	         static SCHEMA_GEN: &[ConfigKey] = &[\n",
289	    );
290	    for key in keys {
291	        let homes = key
292	            .homes
293	            .iter()
294	            .map(|h| match h.as_str() {
295	                "user" => "Home::User",
296	                "workspace-code" => "Home::WorkspaceCode",
297	                "workspace-bot" => "Home::WorkspaceBot",
298	                other => panic!("vc-config.md: [{}] unknown home {other:?}", key.path),
299	            })
300	            .collect::<Vec<_>>()
301	            .join(", ");
302	        let kind = match key.kind.as_str() {
303	            "str" => "ValueKind::Str",
304	            "usize" => "ValueKind::Usize",
305	            "item-list" => "ValueKind::ItemList",
306	            other => panic!("vc-config.md: [{}] unknown kind {other:?}", key.path),
307	        };
308	        let opt = |v: &Option<String>| match v {
309	            Some(s) => format!("Some({s:?})"),
310	            None => "None".to_string(),
311	        };
312	        // `blob/HEAD` resolves to the repo's default branch at
313	        // click time, so the base names only the repo and no
314	        // branch is baked in (a build-time branch would point
315	        // shipped references at whatever the builder had checked
316	        // out). The join is GitHub-shaped; a host needing another
317	        // shape uses the per-key `reference` override.
318	        let reference = key.reference.clone().unwrap_or_else(|| {
319	            format!(
320	                "{}/blob/HEAD/vc-config.md#{}",
321	                base.trim_end_matches('/'),
322	                anchor_slug(&key.path)
323	            )
324	        });
325	        out.push_str(&format!(
326	            "    ConfigKey {{\n\
327	             \x20       path: {path:?},\n\
328	             \x20       homes: &[{homes}],\n\
329	             \x20       kind: {kind},\n\
330	             \x20       default: {default},\n\
331	             \x20       required: {required},\n\
332	             \x20       dynamic: {dynamic},\n\
333	             \x20       doc: {doc:?},\n\
334	             \x20       used_by: {used_by:?},\n\
335	             \x20       example: {example},\n\
336	             \x20       reference: {reference:?},\n\
337	             \x20   }},\n",
338	            path = key.path,
339	            default = opt(&key.default),
340	            required = key.required,
341	            dynamic = key.path.contains('<'),
342	            doc = key.doc,
343	            used_by = key.used_by,
344	            example = opt(&key.example),
345	            reference = reference,
346	        ));
347	    }
348	    out.push_str("];\n");
349	
350	    for key in keys {
351	        let Some(default) = &key.default else {
352	            continue;
353	        };
354	        if key.path.contains('<') {
355	            continue;
356	        }
357	        let name = format!(
358	            "{}_DEFAULT",
359	            key.path.to_uppercase().replace(['.', '-'], "_")
360	        );
361	        // Not every generated constant has a non-test consumer
362	        // (e.g. the items default's runtime twin is
363	        // `ItemSet::BUILTIN`), so silence dead_code per constant.
364	        out.push_str("#[allow(dead_code)]\n");
365	        match key.kind.as_str() {
366	            "usize" => out.push_str(&format!("pub const {name}: usize = {default};\n")),
367	            _ => out.push_str(&format!("pub const {name}: &str = {default:?};\n")),
368	        }
369	    }
370	    out
371	}
372	
373	/// Parse the prototype and write the generated schema module
374	/// into `$OUT_DIR/config_schema_gen.rs`.
375	fn generate_config_schema(manifest_dir: &str) {
376	    let proto_path = Path::new(manifest_dir).join("vc-config.md");
377	    println!("cargo::rerun-if-changed={}", proto_path.display());
378	    println!(
379	        "cargo::rerun-if-changed={}",
380	        Path::new(manifest_dir).join("src/md_fence.rs").display()
381	    );
382	    let md = match std::fs::read_to_string(&proto_path) {
383	        Ok(text) => text,
384	        Err(e) => panic!("cannot read {}: {e}", proto_path.display()),
385	    };
386	    let text = match md_to_toml(&md) {
387	        Ok(text) => text,
388	        Err(e) => panic!("{}: {e}", proto_path.display()),
389	    };
390	    let (base, keys) = parse_prototype(&text);
391	    let out_dir = match std::env::var("OUT_DIR") {
392	        Ok(dir) => dir,
393	        Err(e) => panic!("OUT_DIR unset: {e}"),
394	    };
395	    let gen_path = Path::new(&out_dir).join("config_schema_gen.rs");
396	    if let Err(e) = std::fs::write(&gen_path, render_config_schema(&keys, &base)) {
397	        panic!("cannot write {}: {e}", gen_path.display());
398	    }
399	}
400	
401	/// Read the lock beside `Cargo.toml` and emit the version env var;
402	/// enforce the single-name guard first, then generate the config
403	/// schema from the prototype.
404	fn main() {
405	    guard_single_name();
406	
407	    let manifest_dir = match std::env::var("CARGO_MANIFEST_DIR") {
408	        Ok(dir) => dir,
409	        Err(e) => panic!("CARGO_MANIFEST_DIR unset: {e}"),
410	    };
411	    generate_config_schema(&manifest_dir);
412	
413	    let lock_path = Path::new(&manifest_dir).join("Cargo.lock");
414	    println!("cargo::rerun-if-changed={}", lock_path.display());
415	
416	    let lock = match std::fs::read_to_string(&lock_path) {
417	        Ok(text) => text,
418	        Err(e) => panic!("cannot read {}: {e}", lock_path.display()),
419	    };
420	    match jj_lib_version(&lock) {
421	        Some(version) => println!("cargo::rustc-env=JJ_LIB_VERSION={version}"),
422	        None => panic!("no jj-lib package in {}", lock_path.display()),
423	    }
424	}
